import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] sanoq = new int[101];
        for (int i = 0; i < n; i++) {
            sanoq[in.nextInt()]++;
        }
        for (int x = 0; x <= 100; x++) {
            if (sanoq[x] > 0) {
                System.out.println(x + " " + sanoq[x]);
            }
        }
    }
}

solution.cpp:
#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> sanoq(101, 0);
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        sanoq[x]++;
    }
    for (int x = 0; x <= 100; x++) {
        if (sanoq[x] > 0) {
            cout << x << " " << sanoq[x] << endl;
        }
    }
    return 0;
}
